function makeCeptionist(type, options = {}) {
    let output = deepCopy(type),
        bulletType = options.type || defExports.basic2,
        bulletStats = options.bulletStats || [g.blank],
        bulletName = makeExportName(bulletType, 'CeptionistBullet', [bulletStats]),
        turretName = bulletName + 'Turret',
        tankStats = options.tankStats || [g.blank];

    if (!defExports[turretName]) {
        defExports[turretName] = deepCopy(bulletType);
        applyStats(defExports[turretName].GUNS, [g.ceptionist_bullet, ...bulletStats], { propertyEdit: (prop => prop.COLOR = 34) });

        defExports[bulletName] = {
            PARENT: [defExports.bullet],
            HAS_NO_RECOIL: true,
            GUNS: deepCopy(defExports[turretName].GUNS || []),
            TURRETS: deepCopy(defExports[turretName].TURRETS || []),
            PROPS: deepCopy(defExports[turretName].PROPS || []),
            CONTROLLERS: ['alwaysFire']
        };

        if (defExports[turretName].IS_ARENA_CLOSER) {
            defExports[bulletName].DIES_TO_TEAM_BASE = false;
            defExports[bulletName].GO_THRU_OBSTACLES = true;
            defExports[bulletName].LAYER = 12;
        };
    }

    applyStats(output.GUNS, [g.ceptionist, ...tankStats], { shootEdit: (prop => prop.TYPE = defExports[bulletName]) });

    output.LABEL = options.label ?? `${output.LABEL}ceptionist`;
    output.DANGER = options.danger ?? (options.type) ? output.DANGER + 3 : output.DANGER + 2;
    output.TURRETS ||= [];
    output.TURRETS.push({
        POSITION: [9, 0, 0, 0, 0, 1],
        TYPE: [defExports[turretName], {
            COLOR: 34,
            INDEPENDENT: true,
            FACING_TYPE: 'toBound'
        }]
    });
    return output;
};
