const makeSecurity = (type, name) => {
    let output = deepCopy(type),
        gunCount = 20;

    output.LABEL = name || `Security ${output.LABEL}`;
    if (output.DANGER < 7) output.DANGER++;
    output.GUNS = output.GUNS || [];
    output.GUNS.push(...((out = []) => {
        for (let i = 0; i < gunCount; i++) out.push({
            POSITION: [13, 3, -0.01, 0, 0, 360 / gunCount * i, 0],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([g.swarm, g.less_damage, g.bit_less_damage, g.bit_more_range, g.more_range, g.double_size]),
                TYPE: defExports.autoSwarm,
                STAT_CALCULATOR: gunCalcNames.swarm,
                CAN_SHOOT: false,
            }
        });
        return out;
    })());
    output.ON_DAMAGED = (me, them) => {
        if (type.ON_DAMAGED) type.ON_DAMAGED();
        if (global.utility.time() - me.guns[me.guns.length - 1].lastShot.time > 3000) {
            for (let i = 0; i < gunCount; i++) {
                fireGun(me.guns[me.guns.length - i - 1]);
            }
        }
    };
    output.TOOLTIP = 'When you get damaged, a swarm of drones is released';
    return output;
};
const makeMinesweep = (type, name = undefined, options = {}) => {
    let output = deepCopy(type),
        radarWidth = options.width || 0.125,
        radarLength = options.length || 2,
        radarColor = options.radarColor || 11,
        ringColor = options.ringColor || 9,
        aspect = options.aspect || 1,
        dotSize = options.dotSize ?? 1,
        dotLayer = options.dotLayer ?? 0,
        ringLayer = options.ringLayer ?? 1,
        radarLayer = options.radarLayer ?? 1;
    output.LABEL = name || `Naval ${output.LABEL}`;
    if (output.DANGER < 7) output.DANGER++;
    output.SEE_INVISIBLE = true;
    output.SHAPE = output.SHAPE || 132;
    output.TOOLTIP = "Your radar lets you see invisible players.";
    output.PROPS = output.PROPS || [];
    output.PROPS.push({
        POSITION: [dotSize, 0, 0, 0, dotLayer],
        SHAPE: 0,
        TANK_ORIGIN: false,
        COLOR: ringColor
    }, {
        POSITION: [radarLength, 0, 0, 0, ringLayer],
        SHAPE: 0,
        TANK_ORIGIN: false,
        COLOR: ringColor,
        RING: (radarLength - 0.1) / radarLength
    }, {
        POSITION: [1, 0, 0, 0, radarLayer],
        SHAPE: [
            [radarWidth, 0],
            [-radarWidth, 0],
            [-radarWidth * aspect, radarLength],
            [radarWidth * aspect, radarLength]
        ],
        TANK_ORIGIN: false,
        RPM: -2.25,
        COLOR: radarColor
    }, {
        POSITION: [radarWidth + 0.175, 0, 0, 0, radarLayer],
        SHAPE: 0,
        TANK_ORIGIN: false,
        COLOR: radarColor
    });
    return output;
};
const makeFlail = (exportName, name, options = {}) => {
    let stats = options.stats || [g.blank];
    let endColor = options.endColor || 16;
    let endGuns = options.endGuns || [];
    let endTurrets = options.endTurrets || [{
        POSITION: [20.5, 0, 0, 0, 360, 0],
        TYPE: defExports.smasherBody
    }];
    let endSize = options.endSize || 45;
    let endSpacing = options.endSpacing || 55;
    let endDistance = options.endDistance || 25;
    let flailDistance = options.flailDistance || 25;
    let bullet = options.bullet || [defExports.bullet, { LABEL: '', ALPHA: 0 }];
    let flailSpacing = options.flailSpacing || 30;
    let flailScale = options.flailScale || 18.5;
    let flailArc = options.flailArc || 0;
    let flailLength = options.flailLength || 5;
    let flailAmount = options.flailAmount || 1;
    let flailSize = options.flailSize || 6;
    let flailAngle = options.flailAngle || 0;
    let guns = options.guns || [];
    let props = options.props || [];
    let body = options.body || {
        SPEED: base.SPEED * .8,
        ACCELERATION: base.ACCEL * .9
    };
    let tankStatNames = statNames[options.statNames] || statNames['flail'];

    defExports[`${exportName}End`] = {
        LABEL: '',
        SYNC_TURRET_SKILLS: true,
        COLOR: endColor,
        GUNS: [{
            POSITION: [1, 16, 1, 0, 0, 180, 0],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([g.lance, g.flail, ...stats]),
                TYPE: bullet,
                AUTOFIRE: true
            }
        }, ...endGuns],
        TURRETS: endTurrets
    };

    let i;

    for (i = 0; i < flailLength; i++) defExports[`${exportName}${i}`] = {
        LABEL: 'Collision',
        BODY: {
            FOV: 1
        },
        COLOR: 16,
        SYNC_TURRET_SKILLS: true,
        GUNS: [{
            POSITION: [i == 0 ? endDistance : flailDistance, 5, 1, 8, 0, flailArc, 0]
        }],
        TURRETS: [{
            POSITION: [i == 0 ? endSize : flailScale, i == 0 ? endSpacing : flailSpacing, 0, flailArc, 0, 1],
            TYPE: defExports[i == 0 ? `${exportName}End` : `${exportName}${i - 1}`]
        }]
    };

    defExports[`${exportName}`] = {
        PARENT: [defExports.genericTank],
        LABEL: name,
        DANGER: 8,
        STAT_NAMES: tankStatNames,
        BODY: body,
        GUNS: guns,
        PROPS: props,
        TURRETS: ((out = []) => {
            for (let j = 0; j < flailAmount; j++) out.push({
                POSITION: [flailSize, 9, 0, 360 / flailAmount * j + flailAngle, 0, 0],
                TYPE: defExports[`${exportName}${i - 1}`]
            });
            return out;
        })()
    };
};
const makeRotary = (type, name, options = {}) => {
    let output = deepCopy(type),
        turretType = options.type || type,
        turretName = makeExportName(turretType, 'RotaryTurret');

    output.GUNS = output.GUNS || [];

    if (!defExports[turretName]) {
        defExports[turretName] = deepCopy(turretType);
        applyStats(defExports[turretName].GUNS, [g.flank, g.auto]);
    }

    output.TURRETS = output.TURRETS || [];
    output.TURRETS.push({
        POSITION: [20, 0, 0, 180, 361, 0],
        TYPE: [defExports[turretName], {
            CONTROLLERS: ['nearestDifferentMaster'],
            INDEPENDENT: true,
            COLOR: 16,
            AI: {
                SKYNET: true
            }
        }]
    }, {
        POSITION: [22, 0, 0, 0, 0, 0],
        TYPE: [defExports.eggBossCircleProp, {
            COLOR: 16
        }]
    });

    if (output.DANGER < 7) output.DANGER++;
    output.LABEL = name || `Rotary ${output.LABEL}`;

    return output;
};
const makeHoming = (type, name, options = {}) => {
    let output = deepCopy(type),
        stats = options.stats || [g.blank];

    applyStats(output.GUNS, [g.homing, ...stats], {
        shootEdit: (prop) => {
            let bulletExport = makeExportName(prop.TYPE, 'HomingBullet');

            if (!defExports[bulletExport]) {
                defExports[bulletExport] = deepCopy(prop.TYPE);
                defExports[bulletExport].LABEL = `Seeking ${defExports[bulletExport].LABEL}`;
                defExports[bulletExport].CONTROLLERS = ['nearestDifferentMaster', 'mapTargetToGoal'];
                defExports[bulletExport].TYPE = 'bullet';
                defExports[bulletExport].MOTION_TYPE = 'swarm';
                defExports[bulletExport].FACING_TYPE = 'smoothWithMotion';
                defExports[bulletExport].INDEPENDENT = true;
                defExports[bulletExport].AI = {
                    BLIND: true
                };
            }

            prop.TYPE = defExports[bulletExport];
        }
    });

    output.TURRETS = output.TURRETS || [];
    output.TURRETS.push({
        POSITION: [10, 0, 0, 0, 0, 1],
        TYPE: [defExports.eggBossCircleProp, {
            COLOR: 238
        }]
    });

    if (output.DANGER < 7) output.DANGER++;
    output.LABEL = name || `Homing ${output.LABEL}`;

    return output;
};
