defExports.carbonFiberTriangle = {
    PARENT: [defExports.triangle],
    LABEL: 'Carbon Fiber Triangle',
    VALUE: 30000,
    COLOR: 9,
    BODY: {
        DAMAGE: 2,
        DENSITY: 80,
        HEALTH: 600,
        RESIST: Math.pow(1.25, 3),
        SHIELD: 80,
        REGEN: .1
    },
    ON_DAMAGED: function(me, them) {
        if (!them || them.topSpeed > .5) return;
        them.topSpeed -= .5;
        setTimeout(() => {
            if (!them.isAlive()) return;
            them.topSpeed += .5;
        }, 5000);
    }
};
