defExports.bountyHunter = {
    PARENT: [defExports.genericTank],
    LABEL: 'Bounty Hunter',
    DANGER: 6,
    BODY: {
        ACCELERATION: base.ACCEL * .6,
        HEALTH: base.HEALTH * 0.9,
        FOV: base.FOV * 1.4
    },
    GUNS: [{
        POSITION: [30, 10, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.sniper, g.assassin, g.ranger, g.bit_less_reload]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [10, 8.5, -1.6, 8, 0, 0, 0]
    }, {
        POSITION: [8, 8.5, -1.6, 8, 0, 0, 0]
    }, {
        POSITION: [6, 8.5, -1.6, 8, 0, 0, 0]
    }, {
        POSITION: [4, 8.5, -1.6, 8, 0, 0, 0]
    }],
    TOOLTIP: "Get extra bullet stats for a long period after each boss or player kill. Get extra score for boss kills.",
    ON_KILL: function (me, them) {
        if (them.type !== "tank" && them.type !== "miniboss") return;
        let multi = 1
        if (them.type === "miniboss") {
            multi += 3
        }
        me.bhKillStreak = me.bhKillStreak !== undefined ? me.bhKillStreak + 1 : 1
        multi /= me.bhKillStreak / 1.75
        function ChangeBulletStats(amount) {
            me.skill.spd += amount * 0.7;
            me.skill.atk += amount;
            me.skill.pen += amount;
            me.skill.str += amount;
        }
        ChangeBulletStats(.5 * multi);
        setTimeout(() => { if (!me.isAlive()) return; ChangeBulletStats(-.5 * multi); me.bhKillStreak--; }, 60000);
    },
};
