defExports.spedDemon = {
    PARENT: [defExports.booster],
    LABEL: "Speed Demon",
    DANGER: 8,
    TOOLTIP: "Taking damage increases your maximum speed for 5 seconds.",
    PROPS: [{
        POSITION: [.45, 0, 0, 0, 1],
        SHAPE: 0,
        COLOR: 261
    }],
    VARIABLES: { counters: 0 },
    ON_DAMAGED: function(me, them) {
        if (me.variables.counters >= 14) return;
        me.SPEED += .5;
        me.ACCELERATION += .25;
        me.variables.counters++;
        me.refreshBodyAttributes();
        setTimeout(() => {
            if (!me.isAlive()) return;
            me.SPEED -= .5;
            me.ACCELERATION -= .25;
            me.variables.counters--;
            me.refreshBodyAttributes();
        }, 5000)
    }
}
