defExports.sparkBullet1 = {
    PARENT: [defExports.missile],
    LABEL: 'Spark',
    HITS_OWN_TYPE: 'hardOnlyDrones',
    MOTION_TYPE: 'glide',
    HAS_NO_RECOIL: true,
    SHAPE: 6,
    GUNS: function(guns = [{
        POSITION: [14, 7, 1, 0, 0, 0, 3],
        PROPERTIES: {
            AUTOFIRE: true,
            SHOOT_ONCE: true,
            SHOOT_SETTINGS: combineStats([g.basic, g.skim, g.sparkle]),
            TYPE: defExports.bullet,
            ON_FIRE: function(gun) {
                gun.body.facingType = 'autospin';
                gun.body.facingTypeSettings.SPEED = .35;
                gun.body.topSpeed = 0;
                gun.body.motionTypeSettings.DAMP = .15;
            }
        }
    }]) {
        for (let i = 1, j = 1; i < 9; i += 2, j++) guns.push({
            POSITION: [14, 7, 1, 0, 0, j, 3 + (i-1)/9],
            PROPERTIES: {
                AUTOFIRE: true,
                SHOOT_SETTINGS: combineStats([g.basic, g.skim, g.sparkle]),
                TYPE: [defExports.bullet, { PERSISTS_AFTER_DEATH: true }]
            }
        }, {
            POSITION: [14, 7, 1, 0, 0, -j, 3 + i/9],
            PROPERTIES: {
                AUTOFIRE: true,
                SHOOT_SETTINGS: combineStats([g.basic, g.skim, g.sparkle]),
                TYPE: [defExports.bullet, { PERSISTS_AFTER_DEATH: true }]
            }
        });
        guns.push({
            POSITION: [14, 7, 1, 0, 0, 0, 3 + 8/9],
            PROPERTIES: {
                AUTOFIRE: true,
                SHOOT_SETTINGS: combineStats([g.basic, g.skim, g.sparkle]),
                TYPE: [defExports.bullet, { PERSISTS_AFTER_DEATH: true }]
            }
        });
        return guns;
    }()
};
