defExports.splitterSummonerAI = makeBossAI(defExports.splitterSummoner, {
    value: 2e5,
    skill: setSkill(2, 9, 3, 6, 6, 5, 9, 6, 2, 2),
    onDead: function({ sockets, ran, Entity }) {
		let x = this.x,
			y = this.y;
		let positions = [
			[30, 30],
			[-30, -30],
			[30, -30],
			[-30, 30]
		],
			names = ran.chooseBossName("b", 5);

		// Core
		let core = new Entity({
			x: x,
			y: y
		});
		core.team = -100;
		core.name = names[4];
		core.define(Class.splitSummonerCoreAI);
		core.settings.broadcastMessage = "A Splitter Core has been defeated!";

		// Summoners
		for (let i = 0; i < 4; i++) {
			let shard = new Entity({
				x: this.x + positions[i][0],
				y: this.y + positions[i][1]
			});
			shard.team = -100;
			shard.name = names[i];
			shard.define(Class.summonerAI);
			shard.onDead = () => {
				for (let i = 0; i < 4; i++) {
					let e = new Entity({ x: shard.x + positions[i][0], y: shard.y + positions[i][0] })
					e.define(Class.splitterSplitterSquare)
					e.ACCELERATION = .015 / (e.size * 0.2);
					let max = 20
					let min = -20
					e.velocity.x = Math.floor(Math.random() * (max - min + 1)) + min;
					e.velocity.y = Math.floor(Math.random() * (max - min + 1)) + min;
					e.team = -100
				}
			}
		}
	}
});
