defExports.superSplitterSummonerAI = makeBossAI(defExports.superSplitterSummoner, {
    value: 6e5,
    skill: setSkill(2, 9, 3, 6, 6, 5, 9, 6, 2, 2),
    onDead: function({ sockets, ran, Entity }) {
		let x = this.x,
			y = this.y;
		let positions = [
			[30, 30],
			[-30, -30],
			[30, -30],
			[-30, 30]
		],
			names = ran.chooseBossName("b", 5);

		// Core
		let core = new Entity({
			x: x,
			y: y
		});
		core.team = -100;
		core.name = names[4];
		core.define(Class.superSplitSummonerCoreAI);
		core.settings.broadcastMessage = "A Super Splitter Core has been defeated!";

		// Splitter Summoners
		for (let i = 0; i < 4; i++) {
			let shard = new Entity({
				x: this.x + positions[i][0],
				y: this.y + positions[i][1]
			});
			shard.team = -100;
			shard.name = names[i];
			shard.define(Class.splitterSummonerAI);
		}
	}
});
