const createLucrehulk = (function () {
    defExports.lucrehulkProp0 = {
        COLOR: 18,
        SHAPE: 5,
        SYNCS_SKILLS: true,
        SYNC_TURRET_SKILLS: true,
        HITS_OWN_TYPE: "shield"
    };

    let lucrehulkPropID = 1;
    function createLucrehulkProp(type, angle, double = false) {
        const key = `lucrehulkProp${lucrehulkPropID++}`;
        defExports[key] = makeAuto(defExports.lucrehulkProp0, {
            label: "",
            type: defExports[type],
            angle: angle
        });

        if (double) {
            defExports[key].TURRETS.push({
                POSITION: [defExports[key].TURRETS[0].POSITION[0] / 2, ...defExports[key].TURRETS[0].POSITION.slice(1)],
                TYPE: defExports[type]
            });
        }

        return key;
    }

    function create(name, bodyStats = {
        health: 1,
        damage: 1,
        speed: 1,
        size: 1
    }, propA, propB, propC, propD, propE, topTurret) {
        return makeAuto({
            PARENT: [defExports.genericTank],
            DANGER: 8,
            COLOR: 18,
            SIZE: 30 * (bodyStats.size ?? 1),
            BODY: {
                SPEED: 2 * (bodyStats.speed ?? 1),
                ACCELERATION: base.ACCEL * .75,
                HEALTH: 2500 * (bodyStats.health ?? 1),
                SHIELD: 10,
                DAMAGE: 7.5 * (bodyStats.damage ?? 1),
                REGEN: .05,
                PUSHABILITY: .1
            },
            FACING_TYPE: ['autospin', { SPEED: .0025 }],
            GUNS: [{
                POSITION: [28, 10, 1.8, 8, 0, 0, 0]
            }],
            TURRETS: [{
                POSITION: [23, 35, 0, 0, 0, 1],
                TYPE: defExports[propB]
            }, {
                POSITION: [23, 35, 0, -36, 0, 1],
                TYPE: defExports[propA]
            }, {
                POSITION: [23, 35, 0, 36, 0, 1],
                TYPE: defExports[propA]
            }, {
                POSITION: [23, 35, 0, -108, 0, 1],
                TYPE: defExports[propD]
            }, {
                POSITION: [23, 35, 0, 108, 0, 1],
                TYPE: defExports[propD]
            }, {
                POSITION: [23, 35, 0, -144, 0, 1],
                TYPE: defExports[propE]
            }, {
                POSITION: [23, 35, 0, 144, 0, 1],
                TYPE: defExports[propE]
            }, {
                POSITION: [23, 35, 0, -72, 0, 1],
                TYPE: defExports[propC]
            }, {
                POSITION: [23, 35, 0, 72, 0, 1],
                TYPE: defExports[propC]
            }]
        }, {
            label: name,
            type: defExports[topTurret],
            size: 12
        });
    }

    return {
        defaultProp: "lucrehulkProp0",
        createLucrehulkProp: createLucrehulkProp,
        create: create
    };
})();

