defExports.xyvAI = {
    PARENT: [defExports.xyv],
    TYPE: 'miniboss',
    VARIES_IN_SIZE: true,
    LEVEL: 60,
    VALUE: 4e5,
    CONTROLLERS: ['nearestDifferentMaster', 'minion' /*, 'fleeAtLowHealth'*/, 'canRepel'],
    AI: {
        NO_LEAD: true
    },
    HITS_OWN_TYPE: 'hard',
    SKILL: setSkill(0, 8, 5, 7, 7, 8, 5, 0, 0, 0),
	ON_DEAD: function({ sockets, ran, Entity }){
		sockets.broadcast("The Implosionist might have been defeated, but the battle is not over yet...");
		let x = this.x,
			y = this.y;
		setTimeout(() => {
			sockets.broadcast("A Summoner, Guardian, and Defender have spawned to avenge The Implosionist!");
			let positions = [
				[x, y + 100, 0, 100],
				[x + 86.602, y - 50, 86.602, -50],
				[x - 86.602, y - 50, -86.602, -50]
			],
				names = [ran.chooseBossName("c", 1), ran.chooseBossName("a-z", 1), ran.chooseBossName("b", 1)].flat();
			for (let i = 0; i < 3; i++) {
				let boss = new Entity({
					x: positions[i][0],
					y: positions[i][1]
				});
				boss.team = -100;
				boss.name = names[i];
				boss.define([Class.guardianAI, Class.summonerAI, Class.defenderAI][i]);
			}
		}, 7500);
	}
};
defExports.antilifeAI = makeBossAI(defExports.antilife, {
    value: 1e9,
    skill: setSkill(0, 8, 5, 7, 7, 8, 5, 0, 0, 0),
    onDead: function({ sockets, ran, Entity}) {
		sockets.broadcast("Beware the Anti-Life…");
		let x = this.x,
			y = this.y,
            names = [
				ran.chooseBossName('c', 16),
				ran.chooseBossName('a-z', 16),
				ran.chooseBossName('b', 16)
			];
		setTimeout(() => {
			sockets.broadcast("Beware the Anti-Life eternally.");
			for (let i = 0; i < 16; i++) {
				let guardians = new Entity({
                    x: x + 250 * Math.cos(i * Math.PI / 8),
                    y: y + 250 * Math.sin(i * Math.PI / 8)
                });
                guardians.name = names[0][i];
				guardians.team = this.team;
                guardians.control.target.x = 250 * Math.cos(i * Math.PI / 8);
                guardians.control.target.y = 250 * Math.sin(i * Math.PI / 8);
				guardians.define(Class.guardianAI);

				let summoners = new Entity({
                    x: x + 400 * Math.cos(i * Math.PI / 8),
                    y: y + 400 * Math.sin(i * Math.PI / 8)
                });
                summoners.name = names[1][i];
				summoners.team = this.team;
                summoners.control.target.x = 400 * Math.cos(i * Math.PI / 8);
                summoners.control.target.y = 400 * Math.sin(i * Math.PI / 8);
				summoners.define(Class.summonerAI);

				let defenders = new Entity({
                    x: x + 550 * Math.cos(i * Math.PI / 8),
                    y: y + 550 * Math.sin(i * Math.PI / 8)
                });
                defenders.name = names[2][i];
				defenders.team = this.team;
                defenders.control.target.x = 550 * Math.cos(i * Math.PI / 8);
                defenders.control.target.y = 550 * Math.sin(i * Math.PI / 8);
				defenders.define(Class.defenderAI);
			}
		}, 10000);
	}
});
