defExports.constAI = {
    PARENT: [defExports.constellation],
    TYPE: 'miniboss',
    LEVEL: 60,
    VALUE: 3e5,
    CONTROLLERS: ['nearestDifferentMaster', 'mapTargetToGoal'],
    AI: { BLIND: true },
    HITS_OWN_TYPE: 'hard',
    SKILL: setSkill(0, 8, 9, 7, 7, 7, 8, 0, 0, 0),
	ON_DEAD: function({ sockets, ran, Entity }) {
		sockets.broadcast("A Constellation may have been defeated, but the battle is not over yet…");
		let x = this.x,
			y = this.y;
		setTimeout(() => {
			sockets.broadcast("Constellation Shards have spawned to avenge the Constellation!");
			let positions = [
				[x + 110, y, -110, 0],
				[x - 110, y, 110, 0],
				[x, y + 110, 0, -110],
				[x, y - 110, 0, 110]
			],
				name = (this.name == '') ? ran.chooseBossName("castle", 1)[0] : this.name;
			for (let i = 0; i < 4; i++) {
				let shard = new Entity({
					x: positions[i][0],
					y: positions[i][1]
				});
				shard.team = -100;
				shard.control.target.x = positions[i][2];
				shard.control.target.y = positions[i][3];
				shard.name = `${util.addBelonging(name)} Shard`;
				shard.define(Class.constShard);
				shard.settings.broadcastMessage = "A Constellation Shard has been defeated!";
			}
			let core = new Entity({
				x: x,
				y: y
			});
			core.team = -100;
			core.control.target.x = core.control.target.y = 100;
			core.name = `${util.addBelonging(name)} Core`;
			core.define(Class.constCore);
			core.settings.broadcastMessage = "A Constellation Core has been defeated!";
		}, 7500);
	}
};
