function makeSanctuary(type, options = {}) {
    let output = deepCopy(type);
    output.NAME = "Sanctuary";
    output.LABEL = output.LABEL.replace("Dominator", "Sanctuary");
    output.LEVEL = 75;
    output.TURRETS = [type.PARENT[0].TURRETS || [], type.TURRETS || []].flat();
    output.TURRETS.push({
        POSITION: [8, 0, 0, 0, 360, 1],
        TYPE: options.turret ?? defExports.sanctuaryTurret
    });
    output.HITS_OWN_TYPE = "pushOnlyTeam";
    output.NO_SPEED_CALCULATION = true;
    return output;
};
