defExports.butaneGas = {
    PARENT: [defExports.bullet],
    MOTION_TYPE: 'glide',
    BODY: {
        HEALTH: 1000,
        SPEED: 1,
        ACCEL: .02,
        RANGE: 250,
        DAMAGE: 0.0175,
        RESIST: 10,
        PENETRATION: 100,
        SHIELD: 1000,
        REGEN: 10,
        DENSITY: .01,
        PUSHABILITY: 0
    },
    DIES_BY_OBSTACLES: false,
    BOUNCE_ON_OBSTACLES: true,
    INVISIBLE: [0, 1, 0.2],
    ON_COLLIDE: (me, them) => {
        if (!them.doesTorch || me.variables.doneCollide) return;
        me.kill()
        me.variables.doneCollide = true
        let gun = me.master.guns[0]
        let ogCanShoot = gun.canShoot
        gun.canShoot = true
        fireGun(gun)
        let child = undefined;
        for (const c of gun.childrenMap.values()) {
            child = c;
        }
        child.velocity.x = me.velocity.x * .75;
        child.velocity.y = me.velocity.y * .75;
        child.x = them.x
        child.y = them.y
        gun.canShoot = ogCanShoot;
    },
};
