defExports.autoOxy = makeAuto(defExports.miniGuardianLauncher, { label: 'Oxygen' }),
    defExports.autoOxy.WEAPON_COLOR = null,
    defExports.autoOxy.GUNS[0].PROPERTIES.COLOR_OVERRIDE = 5,
    defExports.autoOxy.GUNS[3].PROPERTIES.ON_FIRE = gun => {
        const cycleFix1 = gun.body.guns[0].cycle;    
        gun.body.define(Class.greenAutoOxy);
        gun.body.guns[0].cycle = gun.body.guns[1].cycle = cycleFix1; 
        gun.body.upgrades = [];
        setTimeout(() => {
            if (gun.body.isAlive()) {
                const cycleFix2 = gun.body.guns[0].cycle;
                gun.body.define(Class.autoOxy);
                gun.body.guns[0].cycle = gun.body.guns[0].cycle = cycleFix2;
            }
        }, 2000);
    };
