defExports.tankRandomizer = {
    PARENT: [defExports.genericTank],
    LABEL: 'Random Tank',
    SHAPE: 277,
    GUNS: [],
    TURRETS: [],
    PROPS: [],
    ON_DEFINED: (me) => {
        let tankList = [];
        (function add(my) {
            if (tankList.includes(my)) return;
            tankList.push(my);
            for (let key in my) {
                if (key.startsWith("UPGRADES_TIER")) {
                    my[key].forEach(add);
                }
            }
        })(Class.basic);
        me.define(tankList[Math.floor(Math.random() * tankList.length)]);
    }
};
