function genSporeTurrets() {
    const sporulatorTurrets = []
    for (let i = 0, min = -8, max = 8; i < 20; i++) {
        sporulatorTurrets.push({
            POSITION: [
                (Math.random() * 4 | 0) + 2,
                Math.floor(Math.random() * (max - min + 1) + min),
                Math.floor(Math.random() * (max - min + 1) + min),
                0, 0, 1
            ],
            TYPE: defExports.eggBossCircleProp
        })
    }
    return sporulatorTurrets
}
