				let tank = new Entity({
					x: Math.cos(i * Math.PI / 5) + x,
					y: Math.sin(i * Math.PI / 5) + y
				});
                tank.parent = tank.source = self;
				tank.team = self.team;
                tank.settings.independent = true;
                tank.name = `${util.addBelonging(self.name)} Keeper`;
