defExports.redBurstAI = makeBossAI(defExports.bigRedBoss, {
    value: 3e5,
    onDead: function({ sockets, ran, Entity }) {
        sockets.broadcast("A Red Burst may have been defeated, but the battle is not over yet…");
        let x = this.x,
            y = this.y,
            names = ran.chooseBossName("c", 4);
        setTimeout(function() {
            for (let i = 0; i < 4; i++) {
                let boss = new Entity({
                    x: x,
                    y: y
                });
                boss.define(Class.rs1AI);
                boss.name = names[i];
                boss.team = -100;
            }
            sockets.broadcast("Four RS-Ⅰs have spawned to avenge the Red Burst!");
        }, 5000);
    }
});
