defExports.starProjectile = {
    PARENT: [defExports.healBullet],
    LABEL: "Star",
    SHAPE: getAsset('fatStar'),
    ON_COLLIDE: function(me, them) {
        if (them.team === me.team && !them.isDominator && them.type === 'tank' && !them.invuln) {
            them.invuln = true;
            them.grantedInvuln = true;
            them.invulnTime = [Date.now(), 10000];
            them.sendMessage('You are now invulnerable for 10 seconds!');
        }
    },
    GO_THRU_OBSTACLES: true,
    PROPS: [makeAura(3)]
};
defExports.stealthProjectile = {
    PARENT: [defExports.healBullet],
    LABEL: "Carbon Triangle",
    SHAPE: 3,
    ON_COLLIDE: function(me, them) {
        if (them.team === me.team && !them.isDominator && them.type === 'tank' && !them.invuln && !them.invisible[1] && them.alpha === 1) {
            them.alpha = .2;
            them.variables.grantedInvis = true;
            them.sendMessage('You are now invisible for 20 seconds!');
            setTimeout(function() {
                if (them.variables.grantedInvis) {
                    them.alpha = 1;
                    them.sendMessage('Your invisibility has expired!');
                }
            }, 20000);
        }
    },
    GO_THRU_OBSTACLES: true,
    PROPS: [makeAura(9)]
};
