function twistDrone(me, drone, kind) {
    if (!drone) return;
    if (drone.type === "drone" && drone.canNecro && drone.canNecro.includes(kind)) {
        const theirClass = global.exportNames[drone.index],
            theirSettings = drone.master.guns[drone.gunIndex].interpret(),
            theirSkills = drone.master.guns[drone.gunIndex].getSkillRaw();

        drone.source.childrenMap.delete(drone.id);
        drone.parent = null;
        drone.master = drone;
        drone.source = drone;
        drone.controllers = [];
        
        drone.define(Class.genericEntity);
        drone.team = me.team;

        drone.define(Class[theirClass]);
        drone.type = 'crasher';
        drone.label = `Twisted ${drone.label}`;
        drone.color = 34;
        for (let setting in theirSettings) {
            if (setting === "HETERO") {
                drone.heteroMultiplier = theirSettings[setting];
                continue;
            }
            drone[setting] = theirSettings[setting];
        }
        drone.FOV *= 1.5;
        drone.skill.set(theirSkills);
        drone.refreshBodyAttributes();
        drone.invuln = true;
        drone.invulnTime = [Date.now(), 1500];
        
        return true;
    } else return false;
};
function twistTank(me, tank, kind) {
    if (!tank) return;
    if (tank.type === "tank" && tank.canNecro && tank.canNecro.includes(kind)) {

        tank.controllers = [];
        if (tank.socket) {
            tank.socket.status.deceased = true;
            tank.socket.talk("F", ...tank.socket.player.records());
            tank.autoOverride = false;
            tank.sendMessage = (content, color = 0) => {};
            tank.rewardManager = (id, amount) => {};
        }
        
        tank.team = me.team;

        tank.isSentry = true;
        tank.nameColor = '#FFFFFF';
        tank.label = `Twisted ${tank.label}`;
        tank.color = 34;
        tank.define({ CONTROLLERS: ['nearestDifferentMaster', 'mapAltToFire', 'minion'] });
        tank.aiSettings.STRAFE = true;
        if (tank.facingType === 'toTarget') tank.facingType = 'smoothToTarget';
        tank.refreshBodyAttributes();
        tank.invuln = true;
        tank.invulnTime = [Date.now(), 1500];

        tank.childrenMap.forEach(function(c) {
            const theirGunIndex = c.gunIndex;
            c.define(Class.genericEntity);
            c.team = me.team;
            c.master.guns[theirGunIndex].bulletInit(c);
            c.color = 34;
            c.refreshBodyAttributes();
        })

        return true;
    } else return false;
};
