const giveInvuln = (them, time, message) => {
    if (!them) return;
    let master = them;
    while (master.master !== master) master = master.master;
    master.invuln = true;
    master.grantedInvuln = true;
    master.invulnTime = [Date.now(), time];
    master.sendMessage(`You are now invulnerable for ${message}!`);
};
