defExports.polyamorousMarkTwo = {
	PARENT: [defExports.runecast],
	LABEL: "Polyamorous MKⅡ",
    BODY: { RESIST: base.RESIST * 1.5 },
    TURRETS: function(out = [], layers = [
		defExports.arcanistLayer,
		defExports.occultistLayer,
		defExports.invokerLayer,
		defExports.shamanLayer,
		defExports.exorcistorLayer,
		defExports.enchantressLayer2,
		defExports.summonerLayer2,
		defExports.sorcererLayer2,
	]) {
		for (let i = 0; i < layers.length; i++) out.push({
			POSITION: [lerp(20, 3, (i + 1) / layers.length), 0, 0, 0, 360, 1],
			TYPE: layers[i]
		});
		return out;
	}()
};
defExports.polyamorousMarkTwoAI = makeBossAI(defExports.polyamorousMarkTwo, {
	value: 2e6,
    skill: setSkill(2, 9, 3, 6, 6, 5, 9, 1, 2, 2),
    onDead: function({ sockets, ran, Entity }) {
        let mysticals = [Class.sorcererAI, Class.summonerAI, Class.enchantressAI, Class.exorcistorAI, Class.shamanAI, Class.invokeAI, Class.occultAI, Class.arcanistAI, Class.runecastAI],
            x = this.x,
			y = this.y,
            names = ran.chooseBossName('a-z', 9);
		sockets.broadcast("It will stop at nothing to seek what it came for, not even its own grave…");
        setTimeout(function() {
            sockets.broadcast("The Mysticals have arrived!");
            for (let i = 0; i < 9; i++) {
                let mystical = new Entity({
                    x: x + 375 * Math.cos(i * Math.PI / 4.5),
                    y: y + 375 * Math.sin(i * Math.PI / 4.5)
                });
                mystical.name = names[i];
                mystical.team = -100;
                mystical.control.target.x = 375 * Math.cos(i * Math.PI / 4.5);
                mystical.control.target.y = 375 * Math.sin(i * Math.PI / 4.5);
                mystical.define(mysticals[i]);
            }
        }, 5000);
    }
});
