defExports.hzAI30 = makeBossAI(defExports.hz30, {
	value: 3e5,
	controllers: ['nearestDifferentMaster', 'minion', 'canRepel', 'animateOnDistance'],
	variables: {
        animationCase: 2,
        animationDistance: 28,
        done: false
    },
	skill: setSkill(2, 8, 8, 7, 7, 7, 6, 0, 0, 0),
    onDefined: function(me) {
        if (c.IS_BOSS_RUSH) me.defineController('bossRushAI');
    },
    onTick: function(me, entities) {
        entities.forEach(o => {
            if (!me.variables.done && o.isDominator && util.getDistance(o, {
                x: me.control.target.x + me.x,
                y: me.control.target.y + me.y
            }) < o.size * 1.2) {
                me.variables.done = true;
                animate(me, 'hzAI', 30, 14, false, 0, entities);
            }
        })
    },
    onAlt: (me, entities) => animate(me, 'hzAI', 30, 14, false, 0, entities)
});
